"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["9913"],{2552(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"docs":[{"type":"category","label":"Introduction","collapsed":false,"items":[{"type":"link","href":"/StornX/docs/introduction/what-is-stornx","label":"What is StornX?","docId":"introduction/what-is-stornx","unlisted":false},{"type":"link","href":"/StornX/docs/introduction/why-stornx","label":"Why StornX?","docId":"introduction/why-stornx","unlisted":false},{"type":"link","href":"/StornX/docs/introduction/core-concepts","label":"Core Concepts","docId":"introduction/core-concepts","unlisted":false}],"collapsible":true},{"type":"category","label":"Architecture","collapsed":false,"items":[{"type":"link","href":"/StornX/docs/architecture/overview","label":"Overview","docId":"architecture/overview","unlisted":false},{"type":"link","href":"/StornX/docs/architecture/optiscaler","label":"OptiScaler","docId":"architecture/optiscaler","unlisted":false},{"type":"link","href":"/StornX/docs/architecture/optibalancer","label":"OptiBalancer","docId":"architecture/optibalancer","unlisted":false},{"type":"link","href":"/StornX/docs/architecture/integrations","label":"Integrations","docId":"architecture/integrations","unlisted":false}],"collapsible":true},{"type":"category","label":"Getting Started","collapsed":false,"items":[{"type":"link","href":"/StornX/docs/getting-started/prerequisites","label":"Prerequisites","docId":"getting-started/prerequisites","unlisted":false},{"type":"link","href":"/StornX/docs/getting-started/installation","label":"Installation","docId":"getting-started/installation","unlisted":false},{"type":"link","href":"/StornX/docs/getting-started/configuration","label":"Configuration","docId":"getting-started/configuration","unlisted":false}],"collapsible":true},{"type":"category","label":"Guides","items":[{"type":"link","href":"/StornX/docs/guides/use-cases","label":"Use Cases","docId":"guides/use-cases","unlisted":false},{"type":"link","href":"/StornX/docs/guides/tuning","label":"Tuning","docId":"guides/tuning","unlisted":false},{"type":"link","href":"/StornX/docs/guides/troubleshooting","label":"Troubleshooting","docId":"guides/troubleshooting","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Validation & Benchmarks","items":[{"type":"link","href":"/StornX/docs/benchmarks/overview","label":"Overview","docId":"benchmarks/overview","unlisted":false},{"type":"link","href":"/StornX/docs/benchmarks/load-tests","label":"Load Tests","docId":"benchmarks/load-tests","unlisted":false},{"type":"link","href":"/StornX/docs/benchmarks/stress-tests","label":"Stress Tests","docId":"benchmarks/stress-tests","unlisted":false},{"type":"link","href":"/StornX/docs/benchmarks/availability","label":"Availability","docId":"benchmarks/availability","unlisted":false},{"type":"link","href":"/StornX/docs/benchmarks/comparison","label":"Comparison","docId":"benchmarks/comparison","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"link","href":"/StornX/docs/roadmap","label":"Roadmap","docId":"roadmap","unlisted":false},{"type":"link","href":"/StornX/docs/faq","label":"FAQ","docId":"faq","unlisted":false}]},"docs":{"architecture/integrations":{"id":"architecture/integrations","title":"Integrations","description":"StornX is deliberately boring about its dependencies. It reuses what your platform team almost certainly already runs, and it works around the things it cannot find.","sidebar":"docs"},"architecture/optibalancer":{"id":"architecture/optibalancer","title":"OptiBalancer","description":"OptiBalancer is the traffic-shaping engine. While OptiScaler decides where Pods live, OptiBalancer decides what fraction of the requests each Pod receives.","sidebar":"docs"},"architecture/optiscaler":{"id":"architecture/optiscaler","title":"OptiScaler","description":"OptiScaler is the placement and autoscaling engine. It answers two questions every cycle, for every monitored Deployment:","sidebar":"docs"},"architecture/overview":{"id":"architecture/overview","title":"Architecture Overview","description":"StornX is a single controller Pod that orchestrates two cooperating engines - OptiScaler and OptiBalancer - driven by a cron loop and fed by Prometheus, the Kubernetes API and (optionally) Kube-NetLag.","sidebar":"docs"},"benchmarks/availability":{"id":"benchmarks/availability","title":"Availability & Fault Tolerance","description":"Latency and cost are easy to talk about. Availability under failure is the dimension that decides whether a controller belongs in production. The availability benchmark simulates AZ degradation - increasing latency and partial Pod failures in one zone - and measures how the cluster responds.","sidebar":"docs"},"benchmarks/comparison":{"id":"benchmarks/comparison","title":"Comparison Summary","description":"The side-by-side a platform team usually wants for an internal review. Each row is the direction of the change observed in the benchmark workloads, not a single magic number - the numbers depend on the chattiness of your specific service graph, the number of AZs, and the cloud provider.","sidebar":"docs"},"benchmarks/load-tests":{"id":"benchmarks/load-tests","title":"Load Tests","description":"Load tests apply sustained, realistic traffic to a healthy cluster and measure how StornX behaves over time on the four axes that matter: latency, cost, replica count, resource use.","sidebar":"docs"},"benchmarks/overview":{"id":"benchmarks/overview","title":"Validation & Benchmarks","description":"StornX was designed against real production patterns and validated with end-to-end load and stress tests on representative microservice applications. This section summarises the methodology and the headline findings - the goal is to give you confidence that the controller behaves the way the rest of this documentation claims, not to drown you in numbers.","sidebar":"docs"},"benchmarks/stress-tests":{"id":"benchmarks/stress-tests","title":"Stress Tests","description":"Stress tests push the cluster toward the saturation limit. The intent is not to find the maximum RPS - it is to characterise how the system behaves when it cannot serve all requests on time: does it degrade smoothly, oscillate, or fail noisily?","sidebar":"docs"},"faq":{"id":"faq","title":"FAQ","description":"Does StornX replace the Horizontal Pod Autoscaler?","sidebar":"docs"},"getting-started/configuration":{"id":"getting-started/configuration","title":"Configuration Reference","description":"StornX is configured entirely through environment variables, all exposed as Helm chart values. This page is the single source of truth for what each variable does, what its default is, and when you would change it.","sidebar":"docs"},"getting-started/installation":{"id":"getting-started/installation","title":"Installation","description":"StornX is distributed as a Helm chart on Artifact Hub. A single command brings up the controller.","sidebar":"docs"},"getting-started/prerequisites":{"id":"getting-started/prerequisites","title":"Prerequisites","description":"StornX is a thin layer on top of components most production Kubernetes clusters already run. Before installing, make sure the following are in place.","sidebar":"docs"},"guides/troubleshooting":{"id":"guides/troubleshooting","title":"Troubleshooting","description":"StornX is designed to fail safely - a misbehaving cycle simply produces no decision. The patterns below cover the questions support gets most often.","sidebar":"docs"},"guides/tuning":{"id":"guides/tuning","title":"Tuning Guide","description":"The defaults shipped in the Helm chart converge on every workload we have tested. This guide is for the day you want to push StornX further - to react faster, write less often, or trade resilience for efficiency more aggressively.","sidebar":"docs"},"guides/use-cases":{"id":"guides/use-cases","title":"Use Cases","description":"StornX is opinionated, but its scope is narrow enough that it slots into a wide range of platforms. The patterns below are the ones it was designed for.","sidebar":"docs"},"introduction/core-concepts":{"id":"introduction/core-concepts","title":"Core Concepts","description":"Before diving into the architecture, this page defines the vocabulary StornX uses. Each concept maps directly to a Kubernetes or Istio primitive - nothing is invented for its own sake.","sidebar":"docs"},"introduction/what-is-stornx":{"id":"introduction/what-is-stornx","title":"What is StornX?","description":"StornX is a Kubernetes control-plane extension that unifies three responsibilities that are usually handled in isolation by separate, communication-blind components:","sidebar":"docs"},"introduction/why-stornx":{"id":"introduction/why-stornx","title":"Why StornX?","description":"Kubernetes is excellent at running containers. It is much less opinionated about where those containers should run as conditions evolve and how traffic should be distributed among them. StornX exists because those gaps quietly cost teams money, latency, and reliability every single day.","sidebar":"docs"},"roadmap":{"id":"roadmap","title":"Roadmap","description":"StornX has a clear opinion of what it is today and a clear list of what it should become next. Everything below is on the table; nothing is committed to a calendar date.","sidebar":"docs"}}}}')}}]);